let activeHelp=null,helpSequence=0;
function closeContextHelp(){if(!activeHelp)return;clearTimeout(activeHelp.timer);activeHelp.button.setAttribute('aria-expanded','false');activeHelp.button.removeAttribute('aria-describedby');activeHelp.button.removeAttribute('aria-controls');activeHelp.popup.remove();activeHelp=null;}
function bindContextHelp(){document.querySelectorAll('[data-context-help]').forEach(button=>{
 const open=()=>{if(activeHelp?.button===button){clearTimeout(activeHelp.timer);return}closeContextHelp();const popup=document.createElement('div');popup.className='context-help-popup';popup.id=`context-help-${++helpSequence}`;popup.setAttribute('role','tooltip');popup.innerHTML=benchmarkHelp[button.dataset.contextHelp];document.body.append(popup);const state={button,popup,pinned:false,timer:null};activeHelp=state;
 state.position=()=>{const rect=button.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight){closeContextHelp();return}popup.style.left=Math.max(12,Math.min(rect.left,innerWidth-popup.offsetWidth-12))+'px';popup.style.top=Math.max(12,rect.bottom+8+popup.offsetHeight>innerHeight?rect.top-popup.offsetHeight-8:rect.bottom+8)+'px'};
 button.setAttribute('aria-expanded','true');button.setAttribute('aria-describedby',popup.id);button.setAttribute('aria-controls',popup.id);popup.onpointerenter=()=>clearTimeout(state.timer);popup.onpointerleave=()=>scheduleClose();state.position();};
 const scheduleClose=()=>{if(activeHelp?.button===button&&!activeHelp.pinned&&document.activeElement!==button){clearTimeout(activeHelp.timer);activeHelp.timer=setTimeout(closeContextHelp,160)}};
 button.onpointerenter=e=>{if(e.pointerType!=='touch')open()};button.onpointerleave=scheduleClose;button.onfocus=open;button.onblur=()=>{if(activeHelp?.button===button)closeContextHelp()};button.onclick=()=>{if(activeHelp?.button===button&&activeHelp.pinned){closeContextHelp();return}open();activeHelp.pinned=true};
 });}
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&activeHelp){event.preventDefault();closeContextHelp()}});
